CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE companies (id TEXT PRIMARY KEY, name TEXT NOT NULL, mode TEXT NOT NULL CHECK(mode IN ('DEMO','LIVE')), stopped INTEGER NOT NULL DEFAULT 0 CHECK(stopped IN (0,1)), created_at TEXT NOT NULL);
CREATE TABLE users (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role='CEO'), created_at TEXT NOT NULL);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), csrf TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE stores (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), name TEXT NOT NULL, mode TEXT NOT NULL CHECK(mode IN ('DEMO','LIVE')), status TEXT NOT NULL DEFAULT 'INTEGRATION REQUIRED');
CREATE TABLE departments (id TEXT NOT NULL, company_id TEXT NOT NULL REFERENCES companies(id), name TEXT NOT NULL, paused INTEGER NOT NULL DEFAULT 0 CHECK(paused IN(0,1)), PRIMARY KEY(company_id,id));
CREATE TABLE agents (id TEXT NOT NULL, company_id TEXT NOT NULL REFERENCES companies(id), department TEXT NOT NULL, definition TEXT NOT NULL CHECK(json_valid(definition)), paused INTEGER NOT NULL DEFAULT 0 CHECK(paused IN(0,1)), PRIMARY KEY(company_id,id), FOREIGN KEY(company_id,department) REFERENCES departments(company_id,id));
CREATE TABLE projects (id TEXT NOT NULL, company_id TEXT NOT NULL REFERENCES companies(id), name TEXT NOT NULL, objective TEXT NOT NULL, owner TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ACTIVE', created_at TEXT NOT NULL, PRIMARY KEY(company_id,id));
CREATE TABLE tasks (id TEXT NOT NULL, company_id TEXT NOT NULL REFERENCES companies(id), project_id TEXT NOT NULL, agent_id TEXT NOT NULL, objective TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('QUEUED','WORKING','WAITING','WAITING FOR AGENT','WAITING FOR CEO','BLOCKED','FAILED','COMPLETE','CANCELLED')), expected_output TEXT NOT NULL, actual_output TEXT, retry_count INTEGER NOT NULL DEFAULT 0 CHECK(retry_count BETWEEN 0 AND 3), error TEXT, cost_cents INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, completed_at TEXT, PRIMARY KEY(company_id,id), UNIQUE(company_id,project_id,agent_id,objective), FOREIGN KEY(company_id,project_id) REFERENCES projects(company_id,id), FOREIGN KEY(company_id,agent_id) REFERENCES agents(company_id,id));
CREATE TABLE task_dependencies (company_id TEXT NOT NULL, task_id TEXT NOT NULL, depends_on TEXT NOT NULL, PRIMARY KEY(company_id,task_id,depends_on), CHECK(task_id<>depends_on), FOREIGN KEY(company_id,task_id) REFERENCES tasks(company_id,id), FOREIGN KEY(company_id,depends_on) REFERENCES tasks(company_id,id));
CREATE TABLE approvals (id TEXT NOT NULL, company_id TEXT NOT NULL REFERENCES companies(id), agent_id TEXT NOT NULL, tool TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), payload_hash TEXT NOT NULL, risk TEXT NOT NULL CHECK(risk IN('YELLOW','RED')), state TEXT NOT NULL CHECK(state IN('PENDING','APPROVED','REJECTED','CONSUMED')), requested_by TEXT NOT NULL, decided_by TEXT, expires_at INTEGER NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(company_id,id), FOREIGN KEY(company_id,agent_id) REFERENCES agents(company_id,id));
CREATE TABLE memory_items (id TEXT NOT NULL, company_id TEXT NOT NULL REFERENCES companies(id), title TEXT NOT NULL, body TEXT NOT NULL, classification TEXT NOT NULL CHECK(classification IN('FACT','OBSERVATION','HYPOTHESIS','RECOMMENDATION')), category TEXT NOT NULL, evidence TEXT NOT NULL, source_url TEXT, source_date TEXT, confidence REAL NOT NULL CHECK(confidence BETWEEN 0 AND 1), status TEXT NOT NULL CHECK(status IN('ACTIVE','NEEDS VERIFICATION','STALE','SUPERSEDED','REJECTED')), tags TEXT NOT NULL DEFAULT '[]', relationships TEXT NOT NULL DEFAULT '[]', created_by TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, review_at TEXT NOT NULL, expires_at TEXT, PRIMARY KEY(company_id,id));
CREATE TABLE research_items (id TEXT NOT NULL, company_id TEXT NOT NULL, memory_id TEXT NOT NULL, retrieved_at TEXT NOT NULL, PRIMARY KEY(company_id,id), FOREIGN KEY(company_id,memory_id) REFERENCES memory_items(company_id,id));
CREATE TABLE notifications (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), priority TEXT NOT NULL, message TEXT NOT NULL, read INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE audit_logs (sequence INTEGER PRIMARY KEY AUTOINCREMENT, company_id TEXT NOT NULL REFERENCES companies(id), actor TEXT NOT NULL, action TEXT NOT NULL, resource TEXT NOT NULL, result TEXT NOT NULL, details TEXT NOT NULL CHECK(json_valid(details)), created_at TEXT NOT NULL);
CREATE TRIGGER audit_no_update BEFORE UPDATE ON audit_logs BEGIN SELECT RAISE(ABORT,'Audit records are immutable'); END;
CREATE TRIGGER audit_no_delete BEFORE DELETE ON audit_logs BEGIN SELECT RAISE(ABORT,'Audit records are immutable'); END;
CREATE TABLE messages (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id), agent_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN('CEO','ASSISTANT')), body TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(company_id,agent_id) REFERENCES agents(company_id,id));
CREATE TABLE webhook_events (company_id TEXT NOT NULL REFERENCES companies(id), store_id TEXT NOT NULL, event_id TEXT NOT NULL, body_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'RECEIVED', created_at TEXT NOT NULL, PRIMARY KEY(company_id,store_id,event_id));
CREATE INDEX tasks_company_status ON tasks(company_id,status);
CREATE INDEX approvals_company_state ON approvals(company_id,state);
CREATE INDEX memory_company_category ON memory_items(company_id,category,status);
CREATE INDEX audit_company_time ON audit_logs(company_id,sequence);
CREATE INDEX messages_company_agent ON messages(company_id,agent_id,created_at);
